const repaired = fixtures.map(row => {
 const version=versions.find(v=>v.id===row.version_id);
 const evidence=completeEvidenceFixture(row.payload.reportEvidence);
 evidence.seating={...evidence.seating,...buildReportSeating({...pubs[row.version_id],screenPlaneM:version.screenPlaneM})};
 return {...row,payload:{reportEvidence:evidence}};
});
const entities=rows=>({ReportSnapshot:{filter:async query=>rows.filter(r=>r.version_id===query.version_id)}});
for(const row of fixtures) test(row.version_id+' '+row.report_type+' missing row is Incomplete with exact reason',()=>{
 const result=validateReportEvidence(row.payload.reportEvidence,row.report_type);
 assert.equal(result.reason,'seating.per_seat[0].row is missing');
 assert.equal(resolveSavedReportCell({saved:row,currentFingerprints:row.source_fingerprints}).state,'incomplete');
 assert.match(resolveSavedReportCell({saved:row,currentFingerprints:row.source_fingerprints}).reason,/Project Report needs to be completed/);
});
for(const row of repaired) test(row.version_id+' '+row.report_type+' durable rows are complete and Current',()=>{
 const evidence=row.payload.reportEvidence;
 assert.equal(validateReportEvidence(evidence,row.report_type).complete,true);
 assert.equal(resolveSavedReportCell({saved:row,currentFingerprints:row.source_fingerprints}).state,'current');
 assert.deepEqual(evidence.seating.rows,[1,2]); assert.equal(evidence.seating.seats,9);
 assert.deepEqual(evidence.seating.per_seat.map(s=>s.row),[1,1,1,1,2,2,2,2,2]);
 assert.deepEqual(evidence.seating.per_seat.map(s=>s.column),[1,2,3,4,1,2,3,4,5]);
});
test('server reader blocks same missing field for both versions',async()=>{
 for(const version of versions) await assert.rejects(()=>readProposalReportEvidence(entities(fixtures),version.project_id,[version]),/seating.per_seat\[0\]\.row is missing/);
});
test('server reader accepts repaired evidence for both versions',async()=>{
 for(const version of versions) {
  const [result]=await readProposalReportEvidence(entities(repaired),version.project_id,[version]);
  assert.equal(result.source,'report-evidence'); assert.equal(result.snapshot.viewing.per_seat.length,9);
  assert.equal(result.snapshot.seats[0].row,1);
 }
});
test('missing row never manufactured from seat ID',()=>{
 const seating=buildReportSeating({seats:[{id:'seat-r1-c1',priority:'primary',position:{x:1,y:4}}],viewing:[],screenPlaneM:0});
 assert.equal(seating.per_seat[0].row,null);
});
test('complete flag cannot bypass row and overwrite a complete saved row',()=>{
 const saved=repaired[0]; const incoming=structuredClone(saved.payload.reportEvidence); incoming.seating.per_seat[0].row=null;
 const result=resolveEvidenceWrite({existing:saved,incoming});
 assert.equal(result.incomingReady,false);assert.equal(result.preserved,true);
});
test('mismatching frozen identity cannot be Current',()=>{
 const saved=structuredClone(repaired[0]);saved.payload.reportEvidence.identity.version_id='wrong-version';
 assert.equal(resolveSavedReportCell({saved,currentFingerprints:saved.source_fingerprints}).state,'incomplete');
});
test('browser contract is byte-identical to server contract',()=>{
 for(const name of ['reportEvidenceCompleteness','reportEvidenceSeating'])
  assert.equal(fs.readFileSync('shared/'+name+'.js','utf8'),fs.readFileSync('base44/shared/'+name+'.js','utf8'));
});
test('P19 link remains RSP scoped, never per-seat result',()=>{
 for(const row of repaired) for(const seat of row.payload.reportEvidence.seating.per_seat) assert.equal(seat.p19_rsp_ref.scope,'RSP');
});